//# region React table extension interfaces

/**
 * @internal
 * Extension interface to extend the useTable hook options with the UserActions options.
 */
export interface DataTableV2UserActionsOptions<
  TData extends DataTableV2RowData,
> {
  /**
   * Enables columnActions as a feature on the table.
   */
  enableColumnActions?: boolean;

  /** Holds a collection of all cell actions to render when necessary. */
  cellActions?: {
    [key in symbol | string]: Array<
      | ReactNode
      | ((
          column: DataTableV2ColumnDef<TData>,
        ) => ReactElement<PropsWithChildren>)
    >;
  };

  /**
   * Enables cellActions as a feature on the table.
   */
  enableCellActions?: boolean;

  /** Holds a collection of all column actions to render when necessary. */
  columnActions?: {
    [key in symbol | string]: Array<
      | ReactNode
      | ((
          column: DataTableV2ColumnDef<TData>,
        ) => ReactElement<PropsWithChildren>)
    >;
  };

  /**
   * Enables rowActions as a feature on the table.
   */
  enableRowActions?: boolean;

  /** Holds a collection of all row actions to render when necessary. */
  rowActions?: (row: TData) => ReactNode;

  /** Reference map to get to the original (non-exteded version) of the column
   * definition passed by the consumer in order to get emit it with a column or cell action.
   */
  consumerColumnDefMap?: Map<string, DataTableV2ColumnDef<TData>>;
}

/**
 * @internal
 * Extension interface to extend the types of the `HeaderCell` from the tanstack table.
 */
export interface DataTableV2UserActionsHeader {
  /**
   * Defines if the header does have user actions defined
   */
  getCanHeaderUserActions: () => boolean;

  /**
   * Returns the defined user actions that can be passed to the menu content.
   */
  getHeaderUserActions: () => Array<ReactNode> | null;
}

/**
 * @internal
 * Extension interface to extend the types of the `Cell` from the tanstack table.
 */
export interface DataTableV2UserActionsCell {
  /**
   * Defines if the header does have user actions defined
   */
  getCanCellUserActions: () => boolean;

  /**
   * Returns the defined user actions that can be passed to the menu content.
   */
  getCellUserActions: () => Array<ReactNode> | null;
}
//# endregion React table extension interfaces

//# region local util functions

const ACTION_FOR_ALL_COLUMNS = Symbol('Action applies to all columns');

/** Will collect the configured user actions for a specific column. */
function getActionsForColumn<TData extends DataTableV2RowData>(
  columnId: string,
  optionsActions: {
    [key: string | symbol]: Array<
      | ReactNode
      | ((
          column: DataTableV2ColumnDef<TData>,
        ) => ReactElement<PropsWithChildren>)
    >;
  },
): Array<
  | ReactNode
  | ((column: DataTableV2ColumnDef<TData>) => ReactElement<PropsWithChildren>)
> {
  if (optionsActions[columnId]) {
    return (optionsActions[ACTION_FOR_ALL_COLUMNS] ?? []).concat(
      optionsActions[columnId],
    );
  }
  return optionsActions[ACTION_FOR_ALL_COLUMNS] ?? [];
}

//# endregion local util functions

/** Configuration hook for the DataTableV2 UserActions feature */
export function useUserActions<TData>(
  props: DataTableV2Props<TData>,
  options: TableOptions<TData>,
  consumerColumnDefMap: Map<string, DataTableV2ColumnDef<TData>>,
) {
  const configuredActions = useMemo(() => {
    const actions: {
      cellActions: {
        [key in symbol | string]: Array<
          | ReactNode
          | ((
              column: DataTableV2ColumnDef<TData>,
            ) => ReactElement<PropsWithChildren>)
        >;
      };
      columnActions: {
        [key in symbol | string]: Array<
          | ReactNode
          | ((
              column: DataTableV2ColumnDef<TData>,
            ) => ReactElement<PropsWithChildren>)
        >;
      };
      rowActions?: (column: unknown) => ReactNode;
    } = {
      cellActions: {},
      columnActions: {},
      rowActions: undefined,
    };

    // Iterate through the children of the DataTableV2 component in order to
    // find the `ColumnActions`, `CellActions` and `RowActions` definitions.
    React.Children.forEach(props.children, (child) => {
      // Check if the child is of type cell action and insert it into the actions
      // configuration.
      if (_isDataTableV2CellActions(child)) {
        // Determine if the action is targeting all columns or only a specific
        // one.
        const insertion =
          child.props.column === undefined
            ? ACTION_FOR_ALL_COLUMNS
            : child.props.column;
        // Add the collected actions into the valid actions for the column.
        actions.cellActions[insertion] = actions.cellActions[insertion] ?? [];
        actions.cellActions[insertion].push(child.props.children);
      }
      if (_isDataTableV2ColumnActions(child)) {
        // Determine if the action is targeting all columns or only a specific
        // one.
        const insertion =
          child.props.column === undefined
            ? ACTION_FOR_ALL_COLUMNS
            : child.props.column;
        // Add the collected actions into the valid actions for the column.
        actions.columnActions[insertion] =
          actions.columnActions[insertion] ?? [];
        actions.columnActions[insertion].push(child.props.children);
      }
      if (_isDataTableV2RowActions(child)) {
        actions.rowActions = child.props.children;
      }
    });
    return actions;
  }, [props.children]);

  options.consumerColumnDefMap = consumerColumnDefMap;

  options.enableColumnActions =
    Object.keys(configuredActions.columnActions).length > 0;
  options.columnActions = configuredActions.columnActions;

  options.enableCellActions =
    Object.keys(configuredActions.cellActions).length > 0;
  options.cellActions = configuredActions.cellActions;

  options.enableRowActions = configuredActions.rowActions !== undefined;
  options.rowActions = configuredActions.rowActions;

  if (options.enableRowActions) {
    options.columns.push(_ROW_ACTIONS_COLUMN as ColumnDef<TData, unknown>);
  }
}

/**
 * Defines the user action table feature
 */
export const UserActions: TableFeature = {
  createHeader<TData extends RowData, TValue>(
    header: Header<TData, TValue>,
    table: Table<TData>,
  ) {
    header.getCanHeaderUserActions = () => {
      if (header.column.id === _ROW_ACTIONS_COLUMN.id) {
        return false;
      }

      return (
        getActionsForColumn(header.column.id, table.options.columnActions ?? {})
          .length > 0
      );
    };

    header.getHeaderUserActions = memo(
      () => [header.column.id, table.options.columnActions],
      () => {
        const definedActions = getActionsForColumn(
          header.column.id,
          table.options.columnActions ?? {},
        ).map((entry) => {
          // If the entry is a react element, we can directly return it
          if (isElement(entry)) {
            return entry;
          }
          // If it is a function, we will need to resolve the closure first
          if (typeof entry === 'function') {
            if (table.options.consumerColumnDefMap?.has(header.column.id)) {
              return entry(
                // Need to disable non null assertion here because typescript cannot infer
                // the non null type within a map, even if it was queried before with a has check.
                // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
                table.options.consumerColumnDefMap.get(header.column.id)!,
              );
            }
          }
          return null;
        });

        // Make sure to not return an array if there are no actions defined
        // to avoid bleeding the actions prop in the template to the
        // div.
        if (definedActions.length > 0) {
          return definedActions;
        }
        return null;
      },
      {
        key: 'header-user-actions',
      },
    );
  },

  createCell<TData extends RowData, TValue>(
    cell: Cell<TData, TValue>,
    column: Column<TData, TValue>,
    row: Row<TData>,
    table: Table<TData>,
  ) {
    cell.getCanCellUserActions = () => {
      if (column.id === _ROW_ACTIONS_COLUMN.id) {
        return false;
      }

      return (
        getActionsForColumn(column.id, table.options.cellActions ?? {}).length >
        0
      );
    };

    cell.getCellUserActions = () => {
      const definedActions = getActionsForColumn(
        column.id,
        table.options.cellActions ?? {},
      ).map((entry) => {
        // If the entry is a react element, we can directly return it
        if (isElement(entry)) {
          return entry;
        }
        // If it is a function, we will need to resolve the closure first
        if (typeof entry === 'function') {
          if (table.options.consumerColumnDefMap?.has(column.id)) {
            return entry(
              // Need to disable non null assertion here because typescript cannot infer
              // the non null type within a map, even if it was queried before with a has check.
              // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
              table.options.consumerColumnDefMap.get(column.id)!,
            );
          }
        }
        return null;
      });
      // Make sure to not return an array if there are no actions defined
      // to avoid bleeding the actions prop in the template to the
      // div.
      if (definedActions.length > 0) {
        return definedActions;
      }
      return null;
    };
  },
};

// User action context that provides the current column
// to the user action.
const DataTableV2UserActionContext = createContext<{
  // We cannot use the TData generic in a context and it also would not make a lot of sense, as the context generic could not be
  // carried over.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  column: Column<any> | null;
}>({
  column: null,
});

/**
 * Allows access to the column within provided user actions.
 * @internal
 */
export function _useDataTableV2UserActionContext() {
  const { column } = useContext(DataTableV2UserActionContext);

  // Assert for safe access to  the column.
  if (column === null) {
    throw new Error(
      'Column for context is not defined. This should never happen, please check your actions nesting.',
    );
  }

  return { column };
}

/**
 * @internal
 * Header component for the Row Actions column.
 */
function _RowActionHeader() {
  const intl = useIntl();
  return intl.formatMessage(dataTableMessages.actionColumnHeader);
}

/**
 * @internal
 * Column definition for the Action Column
 *
 */
const _ROW_ACTIONS_COLUMN: ColumnDef<unknown, unknown> = {
  id: 'DataTableV2RowActions',
  accessorFn: () => '',
  header: _RowActionHeader,
  width: DEFAULT_WIDTH_OF_ACTION_COLUMN,
  enableSorting: false,
  cell: ({ row, table }) => {
    if (table.options.rowActions === undefined) {
      return null;
    }
    const actions = table.options.rowActions(row.original);
    const actionItems = React.Children.map(actions, (action) => {
      if (isElement(action)) {
        return action.props?.children;
      }
      return null;
    });
    const density =
      table.getVisualVariantOptions().rowDensity === 'condensed'
        ? 'condensed'
        : 'default';
    return <ActionGroup density={density}>{actionItems}</ActionGroup>;
  },
};

/**
 * Small wrapper that makes sure to only render the defined actions when the menu
 * is open.
 */
function UserActionsMenuWrapper<TData extends DataTableV2RowData>(
  props: PropsWithChildren<{
    actions: Array<ReactNode> | null;
    column: Column<TData> | null;
    className: string;
  }>,
  ref: Ref<HTMLButtonElement>,
) {
  const { actions, column, ...remainingProps } = props;
  const [menuOpen, setMenuOpen] = useState(false);

  return (
    <Menu open={menuOpen} onOpenChange={setMenuOpen}>
      <Menu.Trigger>
        <button ref={ref} {...remainingProps} />
      </Menu.Trigger>
      {menuOpen === true && (
        <DataTableV2UserActionContext.Provider value={{ column }}>
          <Menu.Content>
            {/*
           Run all actions through a React.Children map so they will receive
           an automatic key and do not violate react key map rules.
          */}
            {React.Children.map(actions, (child) => child)}
          </Menu.Content>
        </DataTableV2UserActionContext.Provider>
      )}
    </Menu>
  );
}

/**
 * @internal
 */
export const _UserActionsMenuWrapper = forwardRef(UserActionsMenuWrapper);
